import { seededRange } from "../../geometry";
import { canvasFont } from "../../textures";

/**
 * Shared look for the vintage wall maps in the places frames.
 *
 * Map data modules (generated by `scripts/maps/*.mjs`) hold pre-projected,
 * quantized geometry in a normalized space `MAP_W` x `MAP_H` whose aspect
 * matches the frame's picture opening. Rings and polylines are flat arrays
 * `[x0, y0, x1, y1, ...]` of integers in that space, y pointing down.
 */

export const MAP_W = 10000;
/** Matches the picture opening aspect in PlacesFrames (OW 0.54 x OH 0.56). */
export const MAP_H = 10370;

export type Rings = number[][];

export interface MapLayers {
  /** Country fill (closed rings, even-odd for holes). */
  land: Rings;
  /** Neighboring countries (closed rings). */
  neighbors: Rings;
  /** Lakes drawn on top of land (closed rings). */
  lakes: Rings;
  /** Internal first-level borders (open polylines). */
  stateLines: Rings;
  /** Parallels and meridians (open polylines). */
  graticule: Rings;
}

export const MAP_COLORS = {
  paper: "#efe2c4",
  paperEdge: "rgba(120,80,30,.28)",
  ocean: "#b9d3cc",
  oceanDeep: "#9fc0bb",
  waterLine: "rgba(60,100,110,.22)",
  landUsa: "#f1d9a0",
  landIndia: "#f0c79a",
  neighbor: "#d7d6b8",
  border: "#6b4a2b",
  neighborBorder: "rgba(107,74,43,.55)",
  stateLine: "rgba(110,70,40,.62)",
  graticule: "rgba(70,110,140,.28)",
  ink: "#3b2a1c",
  inkSoft: "rgba(59,42,28,.7)",
  accent: "#9c3b2a",
} as const;

/** Scale factors from the normalized map space to a canvas of `w` x `h`. */
export function mapScale(w: number, h: number): { sx: number; sy: number } {
  return { sx: w / MAP_W, sy: h / MAP_H };
}

/** Append rings or polylines to the current path (call `g.beginPath()` first). */
export function pathRings(g: CanvasRenderingContext2D, rings: Rings, sx: number, sy: number, closed = true): void {
  for (const r of rings) {
    if (r.length < 4) continue;
    g.moveTo(r[0] * sx, r[1] * sy);
    for (let i = 2; i < r.length; i += 2) g.lineTo(r[i] * sx, r[i + 1] * sy);
    if (closed) g.closePath();
  }
}

/** Fill (and optionally stroke) a set of closed rings. */
export function fillRings(
  g: CanvasRenderingContext2D,
  rings: Rings,
  sx: number,
  sy: number,
  fill: string,
  stroke?: string,
  lineWidth = 1,
): void {
  g.beginPath();
  pathRings(g, rings, sx, sy, true);
  g.fillStyle = fill;
  g.fill("evenodd");
  if (stroke) {
    g.strokeStyle = stroke;
    g.lineWidth = lineWidth;
    g.lineJoin = "round";
    g.stroke();
  }
}

/** Stroke open polylines. */
export function strokeLines(
  g: CanvasRenderingContext2D,
  lines: Rings,
  sx: number,
  sy: number,
  stroke: string,
  lineWidth: number,
  dash: number[] = [],
): void {
  g.beginPath();
  pathRings(g, lines, sx, sy, false);
  g.strokeStyle = stroke;
  g.lineWidth = lineWidth;
  g.lineJoin = "round";
  g.lineCap = "round";
  g.setLineDash(dash);
  g.stroke();
  g.setLineDash([]);
}

/** Ocean base: flat sea color with faint horizontal engraving lines. */
export function drawOcean(g: CanvasRenderingContext2D, w: number, h: number): void {
  const sea = g.createRadialGradient(w / 2, h / 2, w * 0.2, w / 2, h / 2, w * 0.8);
  sea.addColorStop(0, MAP_COLORS.ocean);
  sea.addColorStop(1, MAP_COLORS.oceanDeep);
  g.fillStyle = sea;
  g.fillRect(0, 0, w, h);
  g.fillStyle = MAP_COLORS.waterLine;
  for (let y = 3; y < h; y += 7) g.fillRect(0, y, w, 0.8);
}

/**
 * Engraved coastline ripple: a few widening, fading strokes of the land
 * outline drawn before the land fill, so they show only on the water.
 */
export function drawCoastRipple(g: CanvasRenderingContext2D, rings: Rings, sx: number, sy: number): void {
  g.beginPath();
  pathRings(g, rings, sx, sy, true);
  g.lineJoin = "round";
  const passes: [number, number][] = [
    [22, 0.1],
    [14, 0.14],
    [7, 0.2],
  ];
  for (const [lw, a] of passes) {
    g.strokeStyle = `rgba(40,90,100,${a})`;
    g.lineWidth = lw;
    g.stroke();
  }
}

/** Aged paper overlay: tooth speckle and a warm burnt vignette. Draw last (before the neatline). */
export function drawPaper(g: CanvasRenderingContext2D, w: number, h: number, seed: number): void {
  const rand = seededRange(seed);
  for (let i = 0; i < 2600; i++) {
    g.fillStyle = rand(0, 1) > 0.5 ? "rgba(110,80,40,.06)" : "rgba(255,250,235,.1)";
    g.fillRect(rand(0, w), rand(0, h), 2, 2);
  }
  const vig = g.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.35, w / 2, h / 2, Math.max(w, h) * 0.75);
  vig.addColorStop(0, "rgba(120,80,30,0)");
  vig.addColorStop(1, MAP_COLORS.paperEdge);
  g.fillStyle = vig;
  g.fillRect(0, 0, w, h);
}

/** Double-rule border with a paper margin, as on a printed wall map. */
export function drawNeatline(g: CanvasRenderingContext2D, w: number, h: number): void {
  const m = Math.round(w * 0.022);
  g.fillStyle = MAP_COLORS.paper;
  g.fillRect(0, 0, w, m);
  g.fillRect(0, h - m, w, m);
  g.fillRect(0, 0, m, h);
  g.fillRect(w - m, 0, m, h);
  g.strokeStyle = MAP_COLORS.ink;
  g.lineWidth = 3;
  g.strokeRect(m, m, w - m * 2, h - m * 2);
  g.lineWidth = 1;
  g.strokeRect(m - 6, m - 6, w - (m - 6) * 2, h - (m - 6) * 2);
}

/** Title cartouche centered on (x, y): parchment plaque, double rule, serif title, italic subtitle. */
export function drawCartouche(
  g: CanvasRenderingContext2D,
  x: number,
  y: number,
  title: string,
  subtitle?: string,
  titleSize = 40,
): void {
  g.font = canvasFont("display", titleSize, 700);
  const tw = g.measureText(title).width;
  let sw = 0;
  if (subtitle) {
    g.font = canvasFont("display", titleSize * 0.46, 400, "italic");
    sw = g.measureText(subtitle).width;
  }
  const bw = Math.max(tw, sw) + titleSize * 1.4;
  const bh = titleSize * (subtitle ? 2.15 : 1.55);
  const bx = x - bw / 2;
  const by = y - bh / 2;
  g.fillStyle = "rgba(60,40,20,.22)";
  g.fillRect(bx + 4, by + 5, bw, bh);
  g.fillStyle = "#f5ead0";
  g.fillRect(bx, by, bw, bh);
  g.strokeStyle = MAP_COLORS.ink;
  g.lineWidth = 2.5;
  g.strokeRect(bx + 4, by + 4, bw - 8, bh - 8);
  g.lineWidth = 1;
  g.strokeRect(bx + 9, by + 9, bw - 18, bh - 18);
  g.fillStyle = MAP_COLORS.ink;
  g.textAlign = "center";
  g.textBaseline = "middle";
  g.font = canvasFont("display", titleSize, 700);
  g.fillText(title, x, subtitle ? y - titleSize * 0.28 : y + 1);
  if (subtitle) {
    g.fillStyle = MAP_COLORS.accent;
    g.font = canvasFont("display", titleSize * 0.46, 400, "italic");
    g.fillText(subtitle, x, y + titleSize * 0.5);
  }
}

/** Eight-point compass rose centered on (x, y) with radius r, north up. */
export function drawCompass(g: CanvasRenderingContext2D, x: number, y: number, r: number): void {
  g.save();
  g.translate(x, y);
  g.strokeStyle = MAP_COLORS.ink;
  g.lineWidth = 1.5;
  g.beginPath();
  g.arc(0, 0, r * 0.62, 0, Math.PI * 2);
  g.stroke();
  g.beginPath();
  g.arc(0, 0, r * 0.56, 0, Math.PI * 2);
  g.stroke();
  const point = (angle: number, len: number, width: number, dark: boolean) => {
    g.save();
    g.rotate(angle);
    // each point is two half-blades, one inked and one paper
    g.fillStyle = dark ? MAP_COLORS.ink : MAP_COLORS.accent;
    g.beginPath();
    g.moveTo(0, -len);
    g.lineTo(width, 0);
    g.lineTo(0, 0);
    g.fill();
    g.fillStyle = "#f5ead0";
    g.beginPath();
    g.moveTo(0, -len);
    g.lineTo(-width, 0);
    g.lineTo(0, 0);
    g.fill();
    g.strokeStyle = MAP_COLORS.ink;
    g.lineWidth = 1;
    g.beginPath();
    g.moveTo(0, -len);
    g.lineTo(width, 0);
    g.lineTo(-width, 0);
    g.closePath();
    g.stroke();
    g.restore();
  };
  for (let i = 0; i < 4; i++) point(Math.PI / 4 + (i * Math.PI) / 2, r * 0.62, r * 0.12, false);
  for (let i = 0; i < 4; i++) point((i * Math.PI) / 2, r, r * 0.17, true);
  g.fillStyle = MAP_COLORS.ink;
  g.font = canvasFont("display", r * 0.42, 700);
  g.textAlign = "center";
  g.textBaseline = "alphabetic";
  g.fillText("N", 0, -r - r * 0.12);
  g.restore();
}

/** Alternating black/white scale bar starting at (x, y), `px` long, labeled below. */
export function drawScaleBar(g: CanvasRenderingContext2D, x: number, y: number, px: number, label: string): void {
  const segs = 4;
  const hh = 7;
  for (let i = 0; i < segs; i++) {
    g.fillStyle = i % 2 ? "#f5ead0" : MAP_COLORS.ink;
    g.fillRect(x + (px / segs) * i, y, px / segs, hh);
  }
  g.strokeStyle = MAP_COLORS.ink;
  g.lineWidth = 1.2;
  g.strokeRect(x, y, px, hh);
  g.fillStyle = MAP_COLORS.ink;
  g.font = canvasFont("display", 15, 400, "italic");
  g.textAlign = "center";
  g.textBaseline = "top";
  g.fillText(label, x + px / 2, y + hh + 5);
}

/** Letter-spaced italic label for seas and neighbors, centered on (x, y). */
export function drawWaterLabel(
  g: CanvasRenderingContext2D,
  x: number,
  y: number,
  text: string,
  size = 18,
  color: string = MAP_COLORS.inkSoft,
  spacing = 4,
  rotation = 0,
): void {
  g.save();
  g.translate(x, y);
  g.rotate(rotation);
  g.font = canvasFont("display", size, 400, "italic");
  g.fillStyle = color;
  g.textBaseline = "middle";
  g.textAlign = "left";
  const chars = text.split("");
  const total = chars.reduce((acc, ch) => acc + g.measureText(ch).width + spacing, -spacing);
  let cx = -total / 2;
  for (const ch of chars) {
    g.fillText(ch, cx, 0);
    cx += g.measureText(ch).width + spacing;
  }
  g.restore();
}
